        { name: 'id', type: 'string', required: true, description: 'Stable key for the step.' },
        { name: 'title', type: 'ReactNode', required: true, description: 'What the step does.' },
        {
          name: 'description',
          type: 'ReactNode',
          required: false,
          description: 'A secondary line under the title.',
        },
        {
          name: 'status',
