            '`pending | active | complete | error` (plus `current` / `upcoming`). Defaults to `pending`.',
        },
        {
          name: 'detail',
          type: 'ReactNode',
          required: false,
          description: 'Collapsible content; makes the title a disclosure toggle.',
        },
        {
          name: 'icon',
          type: 'ReactNode',
          required: false,
          description: 'Replaces the status glyph in the marker.',
        },
      ],
    },
  ],
  tokens: [
    '--cascivo-color-ai',
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-color-border',
    '--cascivo-color-success',
    '--cascivo-color-destructive',
    '--cascivo-focus-ring',
    '--cascivo-duration-loop-slow',
  ],
  accessibility: {
    role: 'list',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter', 'Space'],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    {
      title: 'Agent steps',
      code: `<ChainOfThought
  items={[
    { id: 'search', title: 'Searched the docs for "refund policy"', status: 'complete' },
    { id: 'read', title: 'Reading 3 pages', status: 'active' },
    { id: 'answer', title: 'Write the answer', status: 'pending' },
  ]}
/>`,
    },
    {
      title: 'With collapsible detail',
      code: `<ChainOfThought
  items={[
    {
      id: 'search',
      title: 'Searched the web',
      status: 'complete',
      detail: 'cascivo.com/docs · github.com/cascivo/cascivo · npmjs.com/package/@cascivo/react',
    },
    { id: 'fail', title: 'Fetch pricing page', description: 'The page returned 404.', status: 'error' },
  ]}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['shimmer-text', 'visually-hidden'],
  tags: ['ai', 'agent', 'steps', 'chain-of-thought', 'reasoning', 'progress', 'tools'],
  intent: {
    whenToUse: [
      'Showing the discrete steps an AI agent is taking or took — searches, file reads, tool calls',
      'Letting a reader expand a step to see what it found, without cluttering the answer',
    ],
    whenNotToUse: [
      'A free-form reasoning trace — use Reasoning',
      'A user-facing multi-step form or checkout — use Steps',
      'A dated activity feed — use Timeline',
      'One tool invocation with its input and output — use ToolCall',
    ],
    antiPatterns: [
      {
        bad: 'Marking several steps active at once to look busy',
        good: 'One active step at a time; finished steps become complete or error',
        why: 'The active step is announced as the current step (aria-current="step"); more than one makes the position meaningless',
      },
    ],
    related: [
      {
        name: 'Reasoning',
        relationship: 'alternative',
        reason: 'Reasoning holds unstructured thinking text; ChainOfThought holds discrete steps',
      },
      {
        name: 'Timeline',
        relationship: 'alternative',
        reason: 'Same status vocabulary, for dated events rather than agent steps',
      },
      {
        name: 'ToolCall',
        relationship: 'pairs-with',
        reason: 'A step’s detail can contain the ToolCall for that step',
      },
      {
        name: 'AiStatus',
        relationship: 'pairs-with',
        reason: 'AiStatus announces the overall phase; the chain itself is never a live region',
      },
    ],
    a11yRationale:
      'An ordered list whose active step carries aria-current="step" and whose list is aria-busy while any step is active. Each step speaks its state as visually hidden text after the title, because the marker glyph is decorative. Steps with detail are native <details>/<summary> disclosures (Enter/Space), so they work before hydration. Only the active marker pulses, under prefers-reduced-motion: no-preference; the chain is never a live region — pair it with AiStatus to announce progress',
    content: {
      tone: 'Past tense for finished steps ("Searched the docs"), present progressive for the active one ("Reading 3 pages")',
    },
    flexibility: [
      {
        area: 'step content',
        level: 'flexible',
        note: 'Titles, descriptions, detail and icons are any ReactNode',
      },
      {
